/**
 * Sets (or replaces) `input.userId`'s out-of-office window and optional
 * delegate. Only someone who may change roles may set another member's
 * absence; everyone else may only set their own — `memberResource()` plus the
 * `member:manage_absence` ownership escalation in `can()` encodes both halves.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  if (input.endsAt <= input.startsAt) {
    throw new Error("Absence end must be after its start");
  }

  const member = requireFound(
    await memberRepo.findMember(input.orgId, input.userId),
    "Member",
    input.userId,
  );
  assertCan(actor, "member:manage_absence", memberResource(member));

  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot delegate to themselves");
    }
    requireFound(
      await memberRepo.findMember(input.orgId, input.delegateUserId),
      "Member",
      input.delegateUserId,
    );
  }

  return memberRepo.upsertAbsence(input);
}

export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = requireFound(
    await memberRepo.findMember(orgId, userId),
    "Member",
    userId,
  );
  assertCan(actor, "member:manage_absence", memberResource(member));

  await memberRepo.deleteAbsence(orgId, userId);
}

export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);

  requireFound(await memberRepo.findMember(orgId, userId), "Member", userId);

  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence) return null;
  if (absence.endsAt <= toIsoTimestamp(new Date())) return null;

  return absence;
}

/**
 * Resolves who should receive something meant for `userId` right now: the
 * delegate if `userId` is away with one set, otherwise `userId` itself.
 * Delegation is never chained — the delegate is returned as-is even if they
 * are away too.
 */
export async function resolveDelegateOrSelf(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp = toIsoTimestamp(new Date()),
): Promise<UserId> {
  const absence = await memberRepo.findActiveAbsence(orgId, userId, at);
  return absence?.delegateUserId ?? userId;
}

