    body: `A comment was added to issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });

  if (payload.mentionedUserIds.length > 0) {
    const delegates = await Promise.all(
      payload.mentionedUserIds.map((userId) =>
        resolveDelegateOrSelf(payload.orgId, userId),
      ),
    );
    const recipients = [...payload.mentionedUserIds, ...delegates];

    await notify(payload.orgId, "comment_mention", recipients, {
      title: "You were mentioned",
      body: `You were mentioned on issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  }
});

